1	import Ajv from 'ajv';
2	import type {ToolDefinition} from '../../types/ai.js';
3	import type {OutgoingMessage} from '../../types/messages.js';
4	import {log} from '../../shared/logger.js';
5	
6	const ajv = new Ajv();
7	
8	// eslint-disable-next-line @typescript-eslint/no-explicit-any
9	type AjvValidateFn = (data: any) => boolean;
10	type AjvErrorObject = {keyword: string; dataPath: string; params: Record<string, unknown>; message?: string};
11	type CompiledValidator = AjvValidateFn & {errors?: null | AjvErrorObject[]};
12	
13	const fnSchemaCache = new WeakMap<Record<string, unknown>, CompiledValidator>();
14	
15	export interface ToolResponse {
16	  result: string;
17	  clientMessages?: OutgoingMessage[];
18	  suppressAssistantResponse?: boolean;
19	}
20	
21	export interface ToolContext {
22	  userId: string | number;
23	  sessionId?: string;
24	  workspaceId?: string | number;
25	  authHeaders?: {
26	    cookie?: string;
27	    authorization?: string;
28	    host?: string;
29	  };
30	}
31	
32	export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;
33	
34	export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
35	  return typeof response === 'string' ? {result: response} : response;
36	}
37	
38	export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);
39	
40	export interface RegisteredTool {
41	  definition: ToolDefinition;
42	  execute: ToolExecutor;
43	}
44	
45	interface StoredTool {
46	  definitionSource: ToolDefinitionSource;
47	  execute: ToolExecutor;
48	  staticValidator?: CompiledValidator;
49	}
50	
51	export class ToolRegistry {
52	  private readonly tools = new Map<string, StoredTool>();
53	
54	  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
55	    return typeof source === 'function' ? source() : source;
56	  }
57	
58	  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
59	    const resolved = this.resolveDefinition(definition);
60	    let staticValidator: CompiledValidator | undefined;
61	
62	    if (typeof definition !== 'function') {
63	      try {
64	        staticValidator = ajv.compile(resolved.inputSchema) as CompiledValidator;
65	      } catch (err) {
66	        throw new Error(`Tool "${resolved.name}" has an invalid inputSchema: ${(err as Error).message}`, {cause: err});
67	      }
