1	export {ToolRegistry, normalizeToolResponse} from './registry.js';
2	export type {ToolResponse, ToolContext, ToolExecutor, ToolDefinitionSource, RegisteredTool} from './registry.js';
3

1	import type {OutgoingMessage} from './messages.js';
2	
3	export interface TextMessage {
4	  role: 'user' | 'assistant';
5	  content: string;
6	}
7	
8	export interface ToolCallContent {
9	  type: 'tool_use';
10	  toolUseId: string;
11	  name: string;
12	  input: Record<string, unknown>;
13	}
14	
15	export interface ToolResultContent {
16	  type: 'tool_result';
17	  toolUseId: string;
18	  content: string;
19	}
20	
21	export interface ToolUseMessage {
22	  role: 'assistant';
23	  content: ToolCallContent[];
24	}
25	
26	export interface ToolResultMessage {
27	  role: 'user';
28	  content: ToolResultContent[];
29	}
30	
31	export type Message = TextMessage | ToolUseMessage | ToolResultMessage;
32	
33	export interface ToolDefinition {
34	  name: string;
35	  description: string;
36	  inputSchema: Record<string, unknown>;
37	  promptInstructions?: string;
38	  examplePrompts?: string[];
39	}
40	
41	export interface ToolCall {
42	  id: string;
